addHook(MutableHashTable, Thing, Function) := opts -> (store, key, hook) -> (
    -- this is the hashtable of Hooks for a specific key, which stores HookAlgorithms and HookPriority
    store#key ??= new MutableHashTable from {
        HookAlgorithms => new MutableHashTable, -- a mutable hash table "strategy key" => "strategy code"
        HookPriority   => new MutableList};     -- a mutable list of strategy keys, in order
    store = store#key;
    ind := #store.HookPriority; -- index to add the hook in the list; TODO: use Priority to insert in the middle?
    alg := if opts.Strategy =!= null then opts.Strategy else ind;
    if not store.HookAlgorithms#?alg then
    store.HookPriority#ind = alg;
    store.HookAlgorithms#alg = hook), class => language-macaulay2}}}}, DIV{HEADER2{See also}, UL{LI{TOH{Macaulay2Doc :: hooks}}, LI{TOH{Macaulay2Doc :: runHooks}}}}, DIV{DIV{class => waystouse, HEADER2{Ways to use , TT{addHook}, :}, UL{LI{KBD{addHook(MutableHashTable,Thing,Function)}}, LI{KBD{addHook(Sequence,Function)}}, LI{KBD{addHook(Symbol,Function)}}}}, DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{Macaulay2Doc :: addHook},  is , SPAN{a , TO2{Macaulay2Doc :: MethodFunctionWithOptions, method function with options}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{Macaulay2Doc/functions/hooks-doc.m2:181:0}, .}}}}

