o3 : FunctionClosure, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i4 : X.GlobalReleaseHook = globalReleaseFunction

o4 = globalReleaseFunction

o4 : FunctionClosure, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i5 : x' = new X

o5 = x'

o5 : X, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i6 : t = {x,x'}

