o6 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i7 : x = x' = 44

o7 = 44, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i8 : t

o8 = {X{}, X{}}

o8 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i9 : code globalAssignFunction

o9 = /usr/share/Macaulay2/Core/startup.m2.in:193
